/// The row for a boss key, or `None` if the key is unknown.
pub fn boss_row(key: &str) -> Option<&'static BossRow> {
    BOSS_DATA.iter().find(|row| row.key == key)
}

/// Boss keys the game would consider for this ante, least-used only.
///
/// Two filters, and the second is the one that is easy to miss. Showdown
/// bosses appear only on the ante that ends a run; ordinary ones only when it
/// does not. Then the set is narrowed to those used fewest so far, which is
/// why a run does not see the same boss twice while others are unplayed --
/// a uniform draw over all eligible bosses is a different game.
pub fn eligible_bosses(ante: i32, used: &HashMap<String, i32>, win_ante: i32) -> Vec<&'static str> {
    let ante = ante.max(1);
    let finisher = ante % win_ante == 0 && ante >= 2;
    let mut pool: Vec<&'static str> = Vec::new();
    for row in BOSS_DATA {
        if row.showdown {
            if finisher {
                pool.push(row.key);
            }
        } else if row.min_ante <= ante && !finisher {
            pool.push(row.key);
        }
    }

    if pool.is_empty() {
        return Vec::new();
    }
    let fewest = pool.iter().map(|key| *used.get(*key).unwrap_or(&0)).min().unwrap();
    // Keys sorted, because pseudorandom_element sorts a keyed table before it
    // picks and the order therefore decides which key an index lands on.
    let mut out: Vec<&'static str> = pool
        .into_iter()
        .filter(|key| *used.get(*key).unwrap_or(&0) == fewest)
        .collect();
    out.sort_unstable();
    out
}
